//! hero_a02: A02（稻姬）的技能腳本，自己一個 DLL（M3'，m3-rust-codegen-design.md §3）。
//! 技能程式由 build.rs 在每次建置前以 v3_rust.lua 產生到 $OUT_DIR/generated.rs；本檔手寫。
//! 匯出與 base_content 同一種 `Manifest`；host 以 `lib_header_from_path` 逐檔載入。
//!
//! M3' ④：IR 已換成產生的 Rust。原本的手寫 handler 只在 `legacy-handlers` feature 下編譯，給
//! base_content 的重播比對（產生的 Rust 與 handler 每 tick 相同）；DLL 不含它們，M5 完成後刪除。
#![cfg_attr(not(feature = "legacy-handlers"), deny(warnings))]

/// This hero's abilities, generated by build.rs (v3_rust.lua --single) from its v3 document.
pub mod generated {
    include!(concat!(env!("OUT_DIR"), "/generated.rs"));
}

/// The hand-written handlers the generated Rust replaced (replay comparison only).
#[cfg(feature = "legacy-handlers")]
#[allow(non_snake_case, warnings)]
pub mod heroes {
    pub mod A02_inahime;
}
#[cfg(feature = "legacy-handlers")]
pub use ability_kit::ability_builder;

use ability_kit::*;

pub use ability_kit::Manifest_Ref;

/// Module id in the manifest and in scripts-manifest.json.
pub const MODULE_ID: &str = "hero_a02";

/// The root module `dll/` exports as hero_a02.dll.
pub fn get_manifest() -> Manifest_Ref {
    Manifest { units, abilities, dev_reload_runtime_lua_content, module_id, content_marker, content_identity }.leak_into_prefix()
}

#[sabi_extern_fn]
pub fn units() -> RVec<UnitDef> { generated::registry::units() }

#[sabi_extern_fn]
pub fn abilities() -> RVec<AbilityDefFFI> { generated::registry::abilities() }

#[sabi_extern_fn]
fn dev_reload_runtime_lua_content(expected_hash: RStr<'_>) -> RuntimeLuaReloadResultFFI {
    ability_kit::module::dev_reload_runtime_lua_content(MODULE_ID, expected_hash)
}

#[sabi_extern_fn]
fn module_id() -> RStr<'static> { RStr::from_str(MODULE_ID) }

#[sabi_extern_fn]
fn content_marker() -> RStr<'static> { ability_kit::module::content_marker() }

#[sabi_extern_fn]
fn content_identity() -> RStr<'static> { ability_kit::module::content_identity() }

/// The Rust handlers the generated abilities replaced (base_content's replay comparison).
#[cfg(feature = "legacy-handlers")]
pub fn handler_scripts() -> Vec<(&'static str, AbilityScript_TO<'static, RBox<()>>)> {
    use crate::heroes::A02_inahime as a02;
    vec![
        ("a02_venom_arrow", a02::a02_venom_arrow_ffi().script),
        ("a02_wind_prayer", a02::a02_wind_prayer_ffi().script),
        ("a02_wind_drift", a02::a02_wind_drift_ffi().script),
        ("a02_shadow_meld", a02::a02_shadow_meld_ffi().script),
    ]
}

#[cfg(test)]
mod tests {
    #[test]
    fn registers_the_four_generated_abilities() {
        let ids: Vec<String> = super::abilities().iter().map(|a| a.script.ability_id().as_str().to_owned()).collect();
        assert_eq!(ids, ["a02_venom_arrow", "a02_wind_prayer", "a02_wind_drift", "a02_shadow_meld"]);
    }
}
